using System;using System.IO;using System.Linq;using UnityEngine;
namespace LostRealmsOW{public static class HorseProgressionValidation{
 static Vector3 visualPosition;static bool visualBlocked;
 public static void StableView(){var gm=UnityEngine.Object.FindObjectsByType<OpenWorldManager>().First(g=>g.Hero);visualPosition=gm.Hero.transform.position;var f=typeof(OpenWorldManager).GetField("saveBlocked",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);visualBlocked=(bool)f.GetValue(gm);f.SetValue(gm,true);gm.Hero.WarpTo(OpenWorldHorseProgression.Stable+Vector3.right*5);gm.CameraRig.enabled=false;Camera.main.transform.position=gm.Hero.transform.position+new Vector3(5,4,-8);Camera.main.transform.LookAt(OpenWorldHorseProgression.Stable+Vector3.up*7);}
 public static void TamingView(){var gm=UnityEngine.Object.FindObjectsByType<OpenWorldManager>().FirstOrDefault(g=>g.Hero);var horse=UnityEngine.Object.FindObjectsByType<OpenWorldAnimalInteraction>().FirstOrDefault(a=>a.Horse&&!a.Owned);if(!gm||!horse){Debug.LogError("[TamingView] no hero or wild horse");return;}gm.Hero.WarpTo(horse.transform.position+horse.transform.right*2.2f);OpenWorldHorseProgression.Begin(horse);if(gm.CameraRig)gm.CameraRig.enabled=false;var cam=Camera.main;if(cam){var look=horse.transform.position+Vector3.up*1.1f;cam.transform.position=look+horse.transform.right*4.4f+Vector3.up*1.8f-horse.transform.forward*1.6f;cam.transform.LookAt(look);}}
 // Bridge capture helper: "hit" resolves the active ring, "miss" forfeits it, so the
 // overlay can be reviewed mid-round with a single call line.
 public static void TamingBeat(string arg){var p=OpenWorldHorseProgression.Instance;if(!p||!p.Target)return;if(arg=="miss")p.Miss();else p.Tap();Debug.Log(OpenWorldMobileHud.TamingSnapshot());}
 public static void TamingCheck(){Debug.Log(OpenWorldMobileHud.TamingSnapshot());}
 // Bridge capture helper. Modes: early / late / hit / miss / tamed. Starts a real wild-horse
 // round, forces one long-lived ring so a screenshot taken later still shows the design, and
 // blocks saves so a pose can never grant a horse or permanently add handling skill.
 static string[] poseFlags;static bool poseBlocked;
 public static void TamingPose(string arg){var p=OpenWorldHorseProgression.Instance;var gm=UnityEngine.Object.FindObjectsByType<OpenWorldManager>().FirstOrDefault(g=>g.Hero);if(!p||!gm){Debug.LogError("[TamingPose] missing progression or manager");return;}var save=typeof(OpenWorldManager).GetField("saveBlocked",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);if(poseFlags==null){poseFlags=gm.CollectedWorldIds.ToArray();poseBlocked=(bool)save.GetValue(gm);save.SetValue(gm,true);}if(p.Target)p.Cancel();typeof(OpenWorldHorseProgression).GetField("retryAt",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).SetValue(p,0f);var all=UnityEngine.Object.FindObjectsByType<OpenWorldAnimalInteraction>();var horse=all.FirstOrDefault(a=>a.Horse&&!a.Owned);Debug.Log("[TamingPose] "+arg+": interactions "+all.Length+", wild "+(horse?horse.name:"none"));if(!horse){Debug.LogError("[TamingPose] no wild horse in range");return;}gm.Hero.WarpTo(horse.transform.position+horse.transform.right*2.2f);OpenWorldHorseProgression.Begin(horse);if(!p.Target){Debug.LogError("[TamingPose] Begin refused for "+horse.name);return;}if(gm.CameraRig)gm.CameraRig.enabled=false;var cam=Camera.main;if(cam){var look=horse.transform.position+Vector3.up*1.1f;cam.transform.position=look+horse.transform.right*4.4f+Vector3.up*1.8f-horse.transform.forward*1.6f;cam.transform.LookAt(look);}p.Successes=arg=="early"?1:arg=="late"?3:0;p.Mistakes=arg=="late"?1:0;float t=arg=="late"?.72f:.27f;p.Beat=new OpenWorldHorseProgression.TameBeat{Pos=new Vector2(.60f,.48f),Start=Time.unscaledTime-t*30f,Life=30f,Diameter=p.BeatSize,Active=true};typeof(OpenWorldHorseProgression).GetField("nextBeatAt",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).SetValue(p,Time.unscaledTime+9999f);if(arg=="hit")p.Tap();else if(arg=="miss")p.Miss();else if(arg=="tamed"){for(int i=0;i<p.Required;i++)p.Tap();Debug.Log("[TamingPose] tamed state "+p.TameState+" successes "+p.Successes);}}
 public static void EndView(){if(OpenWorldHorseProgression.Instance)OpenWorldHorseProgression.Instance.Cancel();var gm=UnityEngine.Object.FindObjectsByType<OpenWorldManager>().FirstOrDefault(g=>g.Hero);if(!gm)return;var save=typeof(OpenWorldManager).GetField("saveBlocked",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);if(poseFlags!=null){foreach(var a in UnityEngine.Object.FindObjectsByType<OpenWorldAnimalInteraction>().Where(a=>a.Owned))UnityEngine.Object.Destroy(a.gameObject);gm.CollectedWorldIds.Clear();gm.CollectedWorldIds.UnionWith(poseFlags);poseFlags=null;save.SetValue(gm,poseBlocked);}else save.SetValue(gm,visualBlocked);gm.Hero.WarpTo(visualPosition);if(gm.CameraRig){gm.CameraRig.enabled=true;gm.CameraRig.SnapToTarget();}}
 public static void Run(){var gm=UnityEngine.Object.FindObjectsByType<OpenWorldManager>().First(g=>g.Hero);var flags=gm.CollectedWorldIds.ToArray();int gold=gm.Gold,weapon=gm.Hero.EquippedWeaponId;Vector3 pos=gm.Hero.transform.position;var field=typeof(OpenWorldManager).GetField("saveBlocked",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);bool blocked=(bool)field.GetValue(gm);var lines=new System.Collections.Generic.List<string>();void Check(bool ok,string label){lines.Add((ok?"PASS ":"FAIL ")+label);}
 try{field.SetValue(gm,true);gm.CloseMenus();gm.CollectedWorldIds.RemoveWhere(f=>f.StartsWith("horse-"));Check(!OpenWorldWeaponCatalog.Available(17),"retired axe unavailable");gm.Hero.EquipWeapon(17);Check(gm.Hero.EquippedWeaponId==-1,"old equipped axe becomes unarmed");var wild=UnityEngine.Object.FindObjectsByType<OpenWorldAnimalInteraction>().FirstOrDefault(a=>a.Horse&&!a.Owned);if(wild)Check(!wild.Mount(gm.Hero),"wild horse cannot mount without taming");gm.Hero.WarpTo(OpenWorldHorseProgression.Stable+Vector3.right*5);gm.Gold=0;Check(!OpenWorldHorseProgression.Instance.Buy(0)&&gm.Gold==0,"stable rejects insufficient funds");gm.Gold=1000;Check(OpenWorldHorseProgression.Instance.Buy(0)&&gm.Gold==650,"stable charges exactly350");Check(gm.CollectedWorldIds.Contains("horse-owned:0"),"ownership recorded");Check(OpenWorldHorseProgression.Instance.Buy(0)&&gm.Gold==650,"owned horse reselection free");var trialObject=new GameObject("isolated wild horse trial");trialObject.transform.position=gm.Hero.transform.position;var trial=trialObject.AddComponent<OpenWorldAnimalInteraction>();trial.Horse=true;trial.Breed=1;var progress=OpenWorldHorseProgression.Instance;OpenWorldHorseProgression.Begin(trial);Check(progress.Target==trial,"taming challenge starts");progress.Miss();progress.Miss();progress.Miss();Check(!progress.Target&&!gm.CollectedWorldIds.Contains("horse-owned:1"),"three missed rings fail without ownership");typeof(OpenWorldHorseProgression).GetField("retryAt",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).SetValue(progress,0f);OpenWorldHorseProgression.Begin(trial);int required=progress.Required;Check(required>=5&&required<=12,"taming round needs 5-12 rings");int quiet=progress.Successes;progress.Tap();Check(progress.Successes==quiet,"tap without a live ring is ignored");var update=typeof(OpenWorldHorseProgression).GetMethod("Update",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance);int expired=progress.Mistakes;progress.Beat=new OpenWorldHorseProgression.TameBeat{Pos=new Vector2(.5f,.5f),Start=Time.unscaledTime-5f,Life=.2f,Diameter=progress.BeatSize,Active=true};update.Invoke(progress,null);Check(progress.Mistakes==expired+1&&!progress.Beat.Active,"expired ring counts as one miss");bool single=true,consumed=true;for(int i=0;i<required;i++){progress.Beat=new OpenWorldHorseProgression.TameBeat{Pos=new Vector2(.5f,.5f),Start=Time.unscaledTime,Life=5f,Diameter=progress.BeatSize,Active=true};int s=progress.Successes;progress.Tap();single&=progress.Successes==s+1;progress.Tap();consumed&=progress.Successes==s+1;}Check(single,"focused ring tap adds one trust");Check(consumed,"second tap on consumed ring is ignored");Check(gm.CollectedWorldIds.Contains("horse-owned:1")&&gm.CollectedWorldIds.Any(f=>f.StartsWith("horse-skill:1")),"successful ring round grants horse and handling skill");UnityEngine.Object.Destroy(trialObject);Check(OpenWorldHorseProgression.Breeds[1].Speed>OpenWorldHorseProgression.Breeds[0].Speed&&OpenWorldHorseProgression.Breeds[2].Stamina>OpenWorldHorseProgression.Breeds[1].Stamina,"breed speed stamina differ");var data=gm.CaptureAdventure();string dir=Path.Combine(Application.temporaryCachePath,"HorseProgress-"+Guid.NewGuid().ToString("N"));var store=new OpenWorldSaveStore(dir);data.collected=data.collected.Concat(new[]{"ore-ready:2:"+(DateTimeOffset.UtcNow.ToUnixTimeSeconds()+86400)}).ToArray();store.Write(data);var loaded=store.Load();Check(loaded.collected.Contains("horse-owned:0")&&loaded.collected.Any(f=>f.StartsWith("ore-ready:2:")),"ownership and ore deadline survive save round trip");}
 finally{gm.CollectedWorldIds.Clear();gm.CollectedWorldIds.UnionWith(flags);gm.Gold=gold;gm.Hero.EquipWeapon(weapon);gm.Hero.WarpTo(pos);field.SetValue(gm,blocked);foreach(var a in UnityEngine.Object.FindObjectsByType<OpenWorldAnimalInteraction>().Where(a=>a.Owned))UnityEngine.Object.Destroy(a.gameObject);File.WriteAllLines("Docs/QA/HORSE_PROGRESSION.txt",lines);Debug.Log(string.Join("\n",lines));}
 }
}}
